estilos_originais_referencia:
*{box-sizing:border-box}
body{font-family:Arial,sans-serif;color:#17324d;margin:0}
.mfc{max-width:980px;margin:auto;padding:24px 18px 48px}
.brand{text-align:center;font:700 italic 34px Georgia,serif;color:#173f63}
.brand b{color:#d6a400}
h1{text-align:center;color:#173f63;margin:7px 0;font-size:28px}
.sub{text-align:center;font-weight:700}
.actions{text-align:center;margin:16px 0 26px}
.pdfbtn{display:inline-block;background:#173f63;color:#fff!important;text-decoration:none;padding:11px 18px;border-radius:8px;font-weight:700}
.q{border:1px solid #d8e2ea;border-radius:12px;padding:18px;margin:18px 0}
.q h2{font-size:19px;margin:0 0 10px}
.q p{font-size:17px;line-height:1.55}
.visual{background:#f8fbfd;border:1px solid #dce7ee;border-radius:10px;padding:18px;margin:14px 0;overflow:hidden}
.choices,.strips{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}
.choice{text-align:center}
.bar{height:54px;display:flex;max-width:300px;margin:0 auto 8px}
.piece{flex:1;border:2px solid #173f63;border-right:0;background:#fff}
.piece:last-child{border-right:2px solid #173f63}
.piece.on{background:#8fc4e5}
.unequal{height:70px;display:flex;max-width:650px;margin:auto}
.unequal span{border:2px solid #173f63;border-right:0}
.unequal span:last-child{border-right:2px solid #173f63}
.u1{flex:1}.u2{flex:2}.u3{flex:3}
.unequal .on{background:#8fc4e5}
.cards,.magnify,.blankcards{display:flex;justify-content:center;gap:14px;flex-wrap:wrap}
.cards>div,.magnify span,.blankcards div{background:#fff;border:2px solid #2f75a8;border-radius:10px;padding:14px 20px;font-size:20px;text-align:center}
.big>div{min-width:90px}
.nline{position:relative;height:72px;margin:20px 35px;border-top:4px solid #173f63}
.ntick{position:absolute;top:-11px;width:2px;height:20px;background:#173f63}
.ntick span{position:absolute;top:24px;transform:translateX(-50%);white-space:nowrap;font-weight:700}
.domino{display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap}
.dom{border:3px solid #173f63;border-radius:8px;background:#fff;padding:18px;font-size:20px;font-weight:700}
.dom.opt{border-style:dashed}
.arrow{font-size:25px}
.pizzas{display:flex;align-items:center;justify-content:center;gap:18px}
.pizza{width:90px;height:90px;border:4px solid #c8842d;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:60px;color:#f1c27d}
.wall>div{display:flex;max-width:600px;margin:6px auto}
.wall span{height:42px;border:1px solid #173f63;display:flex;align-items:center;justify-content:center}
.w2{width:50%}.w4{width:50%}.w8{width:50%}
.wall .on{background:#8fc4e5}
.jug{display:flex;align-items:center;justify-content:center;gap:20px}
.liquid{width:90px;height:130px;border:4px solid #173f63;border-top:0;position:relative}
.fill{position:absolute;bottom:0;left:0;right:0;background:#8fc4e5}
.tanks{display:flex;justify-content:center;gap:50px}
.tank{width:120px;height:160px;border:4px solid #173f63;border-top:0;position:relative;display:flex;align-items:center;justify-content:center}
.tfill{position:absolute;bottom:0;left:0;right:0;background:#8fc4e5;z-index:0}
.tank b{z-index:1;background:#ffffffcc;padding:5px;border-radius:5px}
.dotset{display:grid;grid-template-columns:repeat(12,22px);gap:8px;justify-content:center}
.dot{width:20px;height:20px;border-radius:50%;border:2px solid #173f63;background:#fff}
.dot.mark{background:#8fc4e5}
.progress{text-align:center}
.prog{display:flex;height:55px;max-width:650px;margin:0 auto 10px;border:2px solid #173f63}
.prog span,.prog i{display:flex;align-items:center;justify-content:center;font-style:normal}
.prog span{background:#8fc4e5}
.prog i{background:#f4d58d}
.speech{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.speech div{background:#fff;border:2px solid #b9cad7;border-radius:18px;padding:14px}
.route12{display:grid;grid-template-columns:repeat(12,1fr);gap:3px}
.route12 span{padding:12px 2px;text-align:center;border:1px solid #173f63;background:#fff}
.route12 .am{background:#8fc4e5}
.route12 .pm{background:#f4d58d}
.lines{height:48px;border-bottom:1px dashed #b9c7d2}
.opts{display:flex;gap:10px;flex-wrap:wrap;margin:10px 0}
.opt{border:1px solid #b9cad7;border-radius:7px;padding:8px 14px}
.gab{margin-top:32px}
.gab details{border:1px solid #c8dce9;border-radius:10px;overflow:hidden}
.gab summary{background:#173f63;color:#fff;padding:13px 18px;font-size:18px;font-weight:700;cursor:pointer;display:flex;justify-content:space-between}
.chev{width:10px;height:10px;border-right:3px solid #fff;border-bottom:3px solid #fff;transform:rotate(45deg)}
.gab details[open] .chev{transform:rotate(225deg)}
.inside{padding:14px 18px;background:#f7fafc}

@media(max-width:650px){
.choices,.strips,.speech{grid-template-columns:1fr}
.dotset{grid-template-columns:repeat(9,20px)}
.route12{grid-template-columns:repeat(6,1fr)}
.mfc{padding:18px 12px}
}

@media print{.actions,.gab{display:none}}
